"use client";

import { useState, useEffect, useRef } from 'react';

const CATEGORY_SEARCH_THEMES: Record<string, string> = {
  'threat_intel': 'cyberpunk underground bunker server terminal command center neon glow',
  'osint': 'dark web surveillance data matrix screen extreme macro electronics hardware',
  'vulnerabilities': 'burnt smoking hardware microchip processor copper motherboard circuits',
  'tools': 'backlit stealth hacker mechanical keyboard glowing binary code terminal',
  'default': 'confidential high-contrast tactical digital warfare cyber tech dark security',
};

const AESTHETIC_MODIFIERS = 'cyberpunk dark photography neon high-contrast subtle cinematic lighting';

const SVG_GRID_PLACEHOLDER = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450"><rect width="800" height="450" fill="%23050505"/><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M 20 0 L 0 0 0 20" fill="none" stroke="%23151515" stroke-width="0.5"/></pattern></defs><rect width="800" height="450" fill="url(%23grid)"/><line x1="0" y1="0" x2="800" y2="450" stroke="%231e1b4b" stroke-width="0.5" opacity="0.3"/><line x1="800" y1="0" x2="0" y2="450" stroke="%231e1b4b" stroke-width="0.5" opacity="0.3"/></svg>`;

// In-memory cache to avoid duplicate API searches
const unsplashCache: Record<string, string[]> = {};

function normalizeCategory(category: string): string {
  if (!category) return 'default';
  const c = category.toLowerCase().trim().replace(/[-\s]/g, '_');
  if (c === 'threat_intel' || c === 'threat_intelligence' || c === 'cyber_news' || c === 'cybersecurity') {
    return 'threat_intel';
  }
  if (c === 'vulnerabilities' || c === 'vulnerability' || c === 'cves' || c === 'cve') {
    return 'vulnerabilities';
  }
  if (c === 'osint') {
    return 'osint';
  }
  if (c === 'tools' || c === 'tool' || c === 'programming' || c === 'networking') {
    return 'tools';
  }
  return 'default';
}

interface CyberArticleImageProps {
  title: string;
  category: string;
  articleId: string;
  featuredImage?: string | null;
  className?: string;
  priority?: boolean;
}

export default function CyberArticleImage({
  title,
  category,
  articleId,
  featuredImage,
  className = '',
  priority = false,
}: CyberArticleImageProps) {
  const [loaded, setLoaded] = useState(false);
  const [unsplashApiUrl, setUnsplashApiUrl] = useState<string | null>(null);
  const [sourceTier, setSourceTier] = useState<'featured' | 'api_unsplash' | 'lorem_flickr' | 'svg'>('featured');
  const imgRef = useRef<HTMLImageElement>(null);

  const normCategory = normalizeCategory(category);
  const baseTheme = CATEGORY_SEARCH_THEMES[normCategory] ?? CATEGORY_SEARCH_THEMES['default'] ?? 'confidential';

  // Purge corporate stopwords and clean non-alphanumeric (Unicode-supported)
  const stopWords = new Set(['strategic', 'analysis', 'assessment', 'executive', 'sitrep', 'report', 'security', 'management', 'risk', 'via', 'and', 'the', 'for', 'with', 'post', 'driven']);
  const cleanKeywords = title
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .split(' ')
    .filter(word => word.length > 3 && !stopWords.has(word))
    .slice(0, 2)
    .join(',');

  const finalQuery = `${baseTheme},${cleanKeywords},${AESTHETIC_MODIFIERS}`;
  const numericSeed = articleId.replace(/[^0-9]/g, '').slice(0, 4) || '42';

  // Load dynamic Unsplash search results client-side
  useEffect(() => {
    let active = true;
    setLoaded(false);

    if (featuredImage) {
      setSourceTier('featured');
      return;
    }

    async function loadDynamicUrl() {
      // Check cache first
      if (unsplashCache[finalQuery]) {
        const cached = unsplashCache[finalQuery];
        if (cached && cached.length > 0) {
          const index = Number(numericSeed) % cached.length;
          if (active) {
            setUnsplashApiUrl(cached[index] ?? null);
            setSourceTier('api_unsplash');
          }
          return;
        }
      }

      try {
        const res = await fetch(`/api/unsplash-search?query=${encodeURIComponent(finalQuery)}`);
        if (!res.ok) throw new Error('Unsplash API query failed');
        const data = await res.json();
        
        if (data.results && data.results.length > 0) {
          const urls = data.results.map((img: any) => `${img.urls.raw}&w=800&h=450&fit=crop&auto=format&q=80`);
          unsplashCache[finalQuery] = urls;
          const index = Number(numericSeed) % urls.length;
          if (active) {
            setUnsplashApiUrl(urls[index] ?? null);
            setSourceTier('api_unsplash');
          }
          return;
        }

        // Fallback search to base category theme
        if (unsplashCache[baseTheme]) {
          const cached = unsplashCache[baseTheme];
          if (cached && cached.length > 0) {
            const index = Number(numericSeed) % cached.length;
            if (active) {
              setUnsplashApiUrl(cached[index] ?? null);
              setSourceTier('api_unsplash');
            }
            return;
          }
        }

        const baseRes = await fetch(`/api/unsplash-search?query=${encodeURIComponent(`${baseTheme},${AESTHETIC_MODIFIERS}`)}`);
        if (!baseRes.ok) throw new Error('Unsplash API base query failed');
        const baseData = await baseRes.json();

        if (baseData.results && baseData.results.length > 0) {
          const urls = baseData.results.map((img: any) => `${img.urls.raw}&w=800&h=450&fit=crop&auto=format&q=80`);
          unsplashCache[baseTheme] = urls;
          const index = Number(numericSeed) % urls.length;
          if (active) {
            setUnsplashApiUrl(urls[index] ?? null);
            setSourceTier('api_unsplash');
          }
          return;
        }

        throw new Error('No Unsplash search results returned');
      } catch (e) {
        console.error('Dynamic Unsplash Engine error, falling back to LoremFlickr:', e);
        if (active) {
          setSourceTier('lorem_flickr');
        }
      }
    }

    loadDynamicUrl();

    return () => {
      active = false;
    };
  }, [featuredImage, finalQuery, baseTheme, numericSeed]);

  // Determine active image source URL
  let displaySrc = '';
  if (sourceTier === 'featured') {
    displaySrc = featuredImage || '';
  } else if (sourceTier === 'api_unsplash') {
    displaySrc = unsplashApiUrl || '';
  } else if (sourceTier === 'lorem_flickr') {
    displaySrc = `https://loremflickr.com/800/450/${encodeURIComponent(`${normCategory},cyberpunk`)}?lock=${numericSeed}`;
  } else {
    displaySrc = SVG_GRID_PLACEHOLDER;
  }

  // Handle image loading and cascading errors
  useEffect(() => {
    const img = imgRef.current;
    if (!img || !displaySrc) return;

    let active = true;

    const handleLoad = () => {
      if (!active) return;
      setLoaded(true);
    };

    const handleError = () => {
      if (!active) return;
      // Advance to next tier on failure
      setSourceTier((prev) => {
        if (prev === 'featured') return 'api_unsplash';
        if (prev === 'api_unsplash') return 'lorem_flickr';
        return 'svg';
      });
      setLoaded(false);
    };

    // Native complete checks
    if (img.complete) {
      if (img.naturalWidth > 0) {
        handleLoad();
      } else {
        handleError();
      }
    }

    img.addEventListener('load', handleLoad);
    img.addEventListener('error', handleError);

    return () => {
      active = false;
      img.removeEventListener('load', handleLoad);
      img.removeEventListener('error', handleError);
    };
  }, [displaySrc]);

  return (
    <div className={`relative overflow-hidden bg-neutral-950 border border-neutral-900 ${className}`}>
      {/* 2027 Premium Animated Skeleton Shimmer Layer */}
      {!loaded && (
        <div className="absolute inset-0 z-10 flex flex-col justify-between p-4 bg-gradient-to-br from-neutral-900 to-neutral-950 animate-pulse">
          <div className="flex justify-between items-center opacity-20">
            <span className="font-mono text-[8px] tracking-widest text-neutral-400">SYS_RECON_LOADING...</span>
            <div className="w-1.5 h-1.5 rounded-full bg-red-500 animate-ping" />
          </div>
          <div className="w-full h-[1px] bg-gradient-to-r from-transparent via-neutral-800 to-transparent opacity-20" />
          <span className="font-mono text-[7px] tracking-widest text-neutral-500 text-right uppercase">{normCategory}</span>
        </div>
      )}

      <img
        ref={imgRef}
        src={displaySrc}
        alt={title}
        className={`w-full h-full object-cover transition-all duration-700 ease-out transform ${loaded ? 'scale-100 opacity-100 filter brightness-90 contrast-115' : 'scale-105 opacity-0'}`}
        loading={priority ? 'eager' : 'lazy'}
      />
    </div>
  );
}
